// 200 clientes quieren hacer 1 pedido a las 0:00. El servicio está caído el primer segundo y después acepta
// como mucho 25 pedidos por cada 100 ms (el resto recibe 503). Cada cliente que falla reintenta según su política.
function prng(semilla) {            // generador con semilla: la misma corrida da siempre la misma salida
  let s = semilla >>> 0;
  return () => { s = (Math.imul(s, 1664525) + 1013904223) >>> 0; return s / 4294967296; };
}
function simular(nombre, espera) {
  const azar = prng(7);
  const CLIENTES = 200, CAIDO_HASTA = 1000, CAPACIDAD = 25, BUCKET = 100;
  const proximo = new Array(CLIENTES).fill(0);   // cuándo vuelve a intentar cada cliente (ms)
  const intento = new Array(CLIENTES).fill(0);
  const hecho = new Array(CLIENTES).fill(false);
  const porBucket = {};
  let total = 0, ultimo = 0, pendientes = CLIENTES;
  for (let b = 0; pendientes > 0 && b < 600; b++) {
    const t0 = b * BUCKET, t1 = t0 + BUCKET;
    const llegan = [];
    for (let c = 0; c < CLIENTES; c++) if (!hecho[c] && proximo[c] >= t0 && proximo[c] < t1) llegan.push(c);
    total += llegan.length; porBucket[b] = llegan.length;
    llegan.sort(() => azar() - 0.5);
    llegan.forEach((c, k) => {
      const acepta = t0 >= CAIDO_HASTA && k < CAPACIDAD;
      if (acepta) { hecho[c] = true; pendientes--; ultimo = t1; }
      else { intento[c]++; proximo[c] = t1 + espera(intento[c], azar); }
    });
  }
  const pico = Math.max(...Object.entries(porBucket).filter(([b]) => b * BUCKET >= CAIDO_HASTA).map(([, n]) => n));
  console.log(`${nombre.padEnd(34)} pedidos totales ${String(total).padStart(5)} | pico tras la caída ${String(pico).padStart(3)} | terminó el último a los ${(ultimo / 1000).toFixed(1)} s`);
}
const BASE = 100, TOPE = 8000;
simular('espera fija de 100 ms', () => 100);
simular('exponencial sin azar', (n) => Math.min(TOPE, BASE * 2 ** (n - 1)));
simular('exponencial con jitter completo', (n, azar) => azar() * Math.min(TOPE, BASE * 2 ** (n - 1)));

// Un circuit breaker chico con reloj inyectado, para verlo en cámara lenta (un pedido por segundo simulado).
class Breaker {
  constructor({ umbral, enfriar, ahora }) {
    Object.assign(this, { umbral, enfriar, ahora, estado: 'cerrado', fallos: 0, desde: 0, probando: false, cambios: [] });
  }
  cambiar(nuevo) { this.cambios.push(`t=${this.ahora()} s: ${this.estado} -> ${nuevo}`); this.estado = nuevo; }
  async llamar(fn) {
    if (this.estado === 'abierto') {
      if (this.ahora() - this.desde < this.enfriar) throw new Error('circuito abierto');
      this.cambiar('semiabierto');
    }
    if (this.estado === 'semiabierto') {
      if (this.probando) throw new Error('circuito abierto');
      this.probando = true;                       // una sola llamada de prueba a la vez
    }
    try {
      const r = await fn();
      this.fallos = 0; this.probando = false;
      if (this.estado !== 'cerrado') this.cambiar('cerrado');
      return r;
    } catch (e) {
      this.fallos++; this.probando = false;
      if (this.estado === 'semiabierto' || this.fallos >= this.umbral) { this.desde = this.ahora(); this.cambiar('abierto'); }
      throw e;
    }
  }
}
let t = 0;                                   // reloj simulado, en segundos
const B = { llamadas: 0 };
async function llamarB() {                   // el servicio B: no contesta entre el segundo 1 y el 12
  B.llamadas++;
  if (t >= 1 && t <= 12) throw new Error('B no contesta');
  return 'ok';
}
const cb = new Breaker({ umbral: 3, enfriar: 5, ahora: () => t });
for (t = 0; t <= 16; t++) {
  const antes = B.llamadas;
  let r; try { r = await cb.llamar(llamarB); } catch (e) { r = e.message; }
  console.log(`t=${String(t).padStart(2)} s  ${r.padEnd(17)} ${B.llamadas > antes ? 'llegó a B' : 'cortado en A'}`);
}
console.log('\nCambios de estado:\n' + cb.cambios.join('\n'));
console.log(`\nLlegaron a B: ${B.llamadas} de 17 pedidos (sin breaker habrían llegado los 17)`);
